  image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m4 17 5-5 4 4 3-3 4 4"/>',
  film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 4v16M17 4v16M3 8h4m10 0h4M3 16h4m10 0h4"/>',
  audio:'<path d="M4 10v4m4-8v12m4-15v18m4-15v12m4-8v4"/>',
